package com.acaivis.model;
import jakarta.persistence.*; import java.math.BigDecimal;
@Entity @Table(name="order_items")
public class OrderItem { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="order_id",nullable=false) private Order order; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="product_id",nullable=false) private Product product; @Column(name="product_name",nullable=false) private String productName; @Column(nullable=false) private String size; @Column(name="unit_price",nullable=false,precision=10,scale=2) private BigDecimal unitPrice; @Column(nullable=false) private Integer quantity; @Column(nullable=false,precision=10,scale=2) private BigDecimal subtotal; public Long getId(){return id;} public Order getOrder(){return order;} public void setOrder(Order v){order=v;} public Product getProduct(){return product;} public void setProduct(Product v){product=v;} public String getProductName(){return productName;} public void setProductName(String v){productName=v;} public String getSize(){return size;} public void setSize(String v){size=v;} public BigDecimal getUnitPrice(){return unitPrice;} public void setUnitPrice(BigDecimal v){unitPrice=v;} public Integer getQuantity(){return quantity;} public void setQuantity(Integer v){quantity=v;} public BigDecimal getSubtotal(){return subtotal;} public void setSubtotal(BigDecimal v){subtotal=v;} }
